template <typename Type, typename ...Args, IS_BASE_OF(AActor, Type)>
FORCEINLINE Type* SpawnActor(Args&&... _args)
{
    Type* _actor = Spawn<Type>(this, forward<Args>(_args)...);
    _actor->Construct();
    _actor->Register();
    return _actor;
}
